def search_topics(query: str):
    terms = {query.lower(), *[query[i:i + 2].lower() for i in range(max(0, len(query) - 1))]}
    scored = sorted(TOPICS, key=lambda t: sum(term in (t["title"] + t["text"]).lower() for term in terms), reverse=True)
    return scored[:4]
